//		Exec(ctx)
func (_c *DecisionCreateBulk) OnConflictColumns(columns ...string) *DecisionUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &DecisionUpsertBulk{
		create: _c,
	}
}

