// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.Decision.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(decision.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *DecisionUpsertBulk) UpdateNewValues() *DecisionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(decision.FieldID)
			}
			if _, exists := b.mutation.ProjectID(); exists {
				s.SetIgnore(decision.FieldProjectID)
			}
			if _, exists := b.mutation.ConversationID(); exists {
				s.SetIgnore(decision.FieldConversationID)
			}
			if _, exists := b.mutation.MessageID(); exists {
				s.SetIgnore(decision.FieldMessageID)
			}
			if _, exists := b.mutation.Position(); exists {
				s.SetIgnore(decision.FieldPosition)
			}
			if _, exists := b.mutation.AskerAgentID(); exists {
				s.SetIgnore(decision.FieldAskerAgentID)
			}
			if _, exists := b.mutation.AskerAgentName(); exists {
				s.SetIgnore(decision.FieldAskerAgentName)
			}
			if _, exists := b.mutation.Key(); exists {
				s.SetIgnore(decision.FieldKey)
			}
			if _, exists := b.mutation.KeyNorm(); exists {
				s.SetIgnore(decision.FieldKeyNorm)
			}
			if _, exists := b.mutation.KeySource(); exists {
				s.SetIgnore(decision.FieldKeySource)
			}
			if _, exists := b.mutation.Version(); exists {
				s.SetIgnore(decision.FieldVersion)
			}
			if _, exists := b.mutation.Question(); exists {
				s.SetIgnore(decision.FieldQuestion)
			}
			if _, exists := b.mutation.Choices(); exists {
				s.SetIgnore(decision.FieldChoices)
			}
			if _, exists := b.mutation.DefaultChoiceID(); exists {
				s.SetIgnore(decision.FieldDefaultChoiceID)
			}
			if _, exists := b.mutation.IntroLength(); exists {
				s.SetIgnore(decision.FieldIntroLength)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(decision.FieldCreatedAt)
			}
		}
	}))
	return u
}

